#!/usr/bin/env node
/**
 * Sync the canonical base theme used by the AI generator from the single source
 * of truth: the DTO-normalized artifacts in the webtrit_appearance_theme package
 * (`canonical/*.json`, generated by that package's `tool/dump_canonical.dart`
 * and drift-guarded by `test/canonical_test.dart`).
 *
 * Source:  <phone>/packages/webtrit_appearance_theme/canonical/*.json
 * Target:  src/features/themes/features/generate/base/*.json
 *
 * Usage:
 *   node tool/sync-base-theme.mjs            # copy source -> base (update)
 *   node tool/sync-base-theme.mjs --check    # exit 1 if base drifted (CI)
 *   WEBTRIT_PHONE_DIR=/path/to/webtrit_phone node tool/sync-base-theme.mjs
 *
 * Defaults WEBTRIT_PHONE_DIR to ../webtrit_phone (sibling checkout).
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, '..');

const phoneDir = process.env.WEBTRIT_PHONE_DIR
  ? resolve(process.env.WEBTRIT_PHONE_DIR)
  : resolve(repoRoot, '..', 'webtrit_phone');

const srcDir = join(phoneDir, 'packages', 'webtrit_appearance_theme', 'canonical');
const dstDir = join(repoRoot, 'src', 'features', 'themes', 'features', 'generate', 'base');

// canonical (package) filename -> base filename (identical names)
const MAP = {
  'color.light.json': 'color.light.json',
  'color.dark.json': 'color.dark.json',
  'widget.light.json': 'widget.light.json',
  'widget.dark.json': 'widget.dark.json',
  'page.light.json': 'page.light.json',
  'page.dark.json': 'page.dark.json',
  'app.config.json': 'app.config.json',
};

const check = process.argv.includes('--check');

if (!existsSync(srcDir)) {
  console.error(`[sync-base-theme] Source not found: ${srcDir}`);
  console.error('Set WEBTRIT_PHONE_DIR to the webtrit_phone checkout.');
  process.exit(2);
}

let drifted = 0;
let updated = 0;

for (const [src, dst] of Object.entries(MAP)) {
  const srcPath = join(srcDir, src);
  const dstPath = join(dstDir, dst);
  if (!existsSync(srcPath)) {
    console.error(`[sync-base-theme] Missing source file: ${srcPath}`);
    process.exit(2);
  }
  const srcRaw = readFileSync(srcPath, 'utf8');
  const dstRaw = existsSync(dstPath) ? readFileSync(dstPath, 'utf8') : null;

  if (srcRaw === dstRaw) continue;

  if (check) {
    drifted++;
    console.error(`[sync-base-theme] DRIFT: ${dst} differs from ${src}`);
  } else {
    writeFileSync(dstPath, srcRaw);
    updated++;
    console.log(`[sync-base-theme] updated ${dst}`);
  }
}

if (check) {
  if (drifted) {
    console.error(`\n[sync-base-theme] ${drifted} file(s) out of sync. Run: npm run sync:base-theme`);
    process.exit(1);
  }
  console.log('[sync-base-theme] base theme is in sync ✓');
} else {
  console.log(updated ? `[sync-base-theme] done (${updated} updated)` : '[sync-base-theme] already in sync ✓');
}
